package com.bank.complexity;

import com.bank.complexity.service.Ledger;
import com.bank.complexity.service.SettlementOrchestrator;
import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: idempotent settlement (exactly-once) + correlation-id tracing.
public class ComplexityDemo {
    private static final Logger log = Logger.getLogger("Complexity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Ledger ledger = new Ledger(log);
        // Rajesh SAV2001 = 1,000,000 ; Priya CUR3001 = 250,000.
        ledger.open("SAV2001", new BigDecimal("1000000"));
        ledger.open("CUR3001", new BigDecimal("250000"));

        SettlementOrchestrator orchestrator = new SettlementOrchestrator(log, ledger);

        // Same request id sent twice (client retried) — must apply EXACTLY once.
        orchestrator.settle("REQ-001", "SAV2001", "CUR3001", new BigDecimal("50000"));
        orchestrator.settle("REQ-001", "SAV2001", "CUR3001", new BigDecimal("50000")); // retry

        log.info(() -> "FINAL SAV2001=" + ledger.balanceOf("SAV2001")
            + " CUR3001=" + ledger.balanceOf("CUR3001"));
    }
}
