package com.bank.complexity.service;

import java.math.BigDecimal;
import java.util.logging.*;

// Runs a transfer through steps, tagging each with a correlation id for traceability.
public class SettlementOrchestrator {
    private final Logger log;
    private final Ledger ledger;

    public SettlementOrchestrator(Logger log, Ledger ledger) {
        this.log = log;
        this.ledger = ledger;
    }

    public void settle(String requestId, String from, String to, BigDecimal amount) {
        String correlationId = "CID-" + requestId;   // trace this transfer across steps
        log.info(() -> "[" + correlationId + "] STEP fraud-check: pass");
        boolean applied = ledger.apply(requestId, from, to, amount);
        if (applied) {
            log.info(() -> "[" + correlationId + "] STEP notify: email + SMS sent");
        } else {
            log.info(() -> "[" + correlationId + "] STEP notify: skipped (not newly applied)");
        }
    }
}
